// housing-ingest answers with ONE item carrying the whole queue. Fan it out so
// each listing is its own item — one refused send then costs one email, not the
// whole pass.
const res = $input.first().json;
if (!res || res.ok !== true) {
  throw new Error('housing-ingest notify_pending failed: ' + JSON.stringify(res).slice(0, 300));
}
const notify = res.notify || [];

// An empty queue is the normal steady state, not a failure: every stored listing
// has already been mailed. Returning [] ends the run quietly. Throwing would
// paint a red execution every ten minutes and train everyone to ignore them — and
// then the one that mattered would look exactly like the others.
if (notify.length === 0) return [];

return notify.map((n) => ({ json: n }));

__NOTIFY_JS__

// --- node body ---
// One alert per queued listing, built by the tested buildListingEmail rather than
// by string concatenation here: every field below (title, address, the listing
// URL) was written by whoever posted the ad, and it all ends up in an HTML body
// and a mail header.
//
// The recipient is the user's OWN inbox. Nothing in this pipeline ever mails a
// portal or a landlord — HOUSING_PLAN.md §5, and it is not a limitation to be
// worked around later.
const TO = $env.JOB_NOTIFY_TO || 'bastianrthomsen@gmail.com';
const now = new Date();

return $input.all().map((item) => {
  const listing = item.json || {};
  const mail = buildListingEmail(listing, { now });
  return {
    json: {
      listing_id: listing.listing_id,
      to: TO,
      subject: mail.subject,
      html: mail.html,
      // n8n's Gmail node sends a single body part, so only `html` is transmitted
      // today. `text` is the text/plain half a raw-MIME sender would attach, and
      // it is what the tests pin the email's CONTENT against independently of its
      // markup. Carrying it makes multipart a one-line change if that node ever
      // gains it.
      text: mail.text,
    },
  };
});

__NOTIFY_JS__

// --- node body ---
// Reached only from the Gmail node's SUCCESS output. notify_result flips the row
// to notified server-side, so posting it for an email that never left would hide
// a listing you were never told about — and on a race lane a listing you hear
// about tomorrow is a listing you did not hear about.
//
// Pairing is by pairedItem, not by position. The error output pulls failed items
// out of this stream, so output-0 index i stops being upstream index i the moment
// one send fails, and that offset would stamp a Gmail message id onto the WRONG
// listing. pairedSourceIndex falls back to the index, which is correct whenever
// nothing failed.
const composed = $('Build Listing Email').all();

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const sent = items[i].json || {};
  const src = composed[pairedSourceIndex(items[i].pairedItem, i)];
  const listingId = src && src.json ? src.json.listing_id : null;

  // No id, no claim. Silently skipping is right here: the row stays pending and
  // comes back next pass, which is strictly better than marking something sent on
  // a guess.
  if (!listingId) continue;

  // Gmail's message resource: `id` is the message, `threadId` the conversation.
  out.push({
    json: {
      action: 'notify_result',
      user_id: $env.NEXUS_USER_ID,
      listing_id: listingId,
      ok: true,
      message_id: sent.id || sent.messageId || null,
    },
  });
}
return out;

// A failed send is not a failed run.
//
// notify_result is posted ONLY from the success output, so a listing whose email
// did not leave the machine stays pending and the next ten-minute pass picks it
// up again. That is the retry. Do not add another one here: Gmail can fail AFTER
// accepting a message, and a retry loop that cannot tell those apart is how the
// same alert arrives four times.
for (const item of $input.all()) {
  const j = item.json || {};
  const err = j.error || j.message || j;
  console.log(
    'listing alert failed, row left pending for the next pass: ' + JSON.stringify(err).slice(0, 300),
  );
}
return [];
